// Generates lib/registry.generated.ts from the folders in sources/ and categories/.
// Runs automatically on install, build and test. Never edit the generated file by hand,
// and never commit it: that is what lets many builders add sources at the same time without clashing.
// Folders starting with "_" (like sources/_template) are ignored.

import { existsSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const ID = /^[a-z0-9][a-z0-9-]*$/;

function folders(dir) {
  const abs = path.join(root, dir);
  if (!existsSync(abs)) return [];
  return readdirSync(abs, { withFileTypes: true })
    .filter((d) => d.isDirectory() && !d.name.startsWith("_") && !d.name.startsWith("."))
    .map((d) => d.name)
    .filter((name) => {
      if (!existsSync(path.join(abs, name, "index.ts"))) {
        console.warn(`gen-registry: skipping ${dir}/${name} (no index.ts)`);
        return false;
      }
      if (!ID.test(name)) throw new Error(`gen-registry: folder name "${dir}/${name}" must be lower-case letters, digits and dashes`);
      return true;
    })
    .sort();
}

const cats = folders("categories");
const srcs = folders("sources");
const out = [
  "// AUTO-GENERATED by scripts/gen-registry.mjs from the folders in categories/ and sources/. Do not edit or commit.",
  'import type { CategoryPlugin, SourcePlugin } from "./plugin";',
  ...cats.map((c, i) => `import c${i} from "../categories/${c}";`),
  ...srcs.map((s, i) => `import s${i} from "../sources/${s}";`),
  "",
  `export const CATEGORY_FOLDERS: string[] = ${JSON.stringify(cats)};`,
  `export const SOURCE_FOLDERS: string[] = ${JSON.stringify(srcs)};`,
  `export const CATEGORY_MODULES: CategoryPlugin[] = [${cats.map((_, i) => `c${i}`).join(", ")}];`,
  `export const SOURCE_MODULES: SourcePlugin[] = [${srcs.map((_, i) => `s${i}`).join(", ")}];`,
  "",
].join("\n");

const file = path.join(root, "lib", "registry.generated.ts");
const prev = existsSync(file) ? readFileSync(file, "utf8") : "";
if (prev !== out) writeFileSync(file, out);
console.log(`gen-registry: ${cats.length} categories, ${srcs.length} sources`);
